#!/usr/bin/env bash
# Convert a VS Code extension into a Tab Sage extension under build/<id>/.
#
# Usage:
#   ./transition.sh --vscode ../my-vscode-extension [options]
#
#   --vscode <dir>          Path to the VS Code extension folder (required).
#   --id <slug>             Override the derived id (^[a-z0-9-]+$).
#   --name <text>           Override the display name.
#   --description <text>    Override the description.
#   --author <text>         Override the author (defaults to "publisher").
#   --homepage <url>        Override the homepage.
#   --version <x.y.z>       Override the version.
#   --permissions p1,p2     Replace the inferred permission set.
#   --matches <pattern>     Match pattern (default "<all_urls>").
#   --run-at <when>         document_start | document_end (default document_end).
#   --entry <file>          Entry JS relative to --vscode (default: package.json "main").
#   --out <dir>             Output folder (default build/<id>).
#   --no-ui                 Do not vendor the Tab Sage UI Kit.
#   --force                 Overwrite an existing output folder.
#   -h, --help              Show this help.
#
# What it does:
#   Reads the VS Code package.json, derives a Tab Sage manifest.json from it,
#   lifts contributes.commands / contributes.keybindings / contributes.configuration
#   into runtime data, inlines the compiled JS, and emits a `vscode` compatibility
#   shim implemented on top of the `tabsage` host API. Simple extensions boot and
#   run; everything without a Tab Sage equivalent degrades to a loud stub that is
#   logged once and listed in the generated README.
#
# What it does not do:
#   It never runs npm. The extension must already be compiled: if package.json
#   "main" points at out/extension.js, run `npm install && npm run compile` in the
#   VS Code extension folder first. Tree views, editor decorations, language
#   servers, grammars, and debug adapters have no Tab Sage equivalent and are not
#   translated.
#
# The output in build/ is a starting point for review, not a finished extension.
# Read it, test it, then copy it to extensions/<id>/ when you are happy with it.
set -euo pipefail

repo_root="$(cd "$(dirname "$0")" && pwd)"

usage() {
  sed -n '2,/^set -euo/p' "$0" | grep '^#' | sed 's/^# \{0,1\}//'
}

VSC_DIR="" ID="" NAME="" DESCRIPTION="" AUTHOR="" HOMEPAGE="" VERSION=""
PERMISSIONS="" MATCHES="" RUN_AT="" ENTRY="" OUT="" WITH_UI=1 FORCE=0

while [ $# -gt 0 ]; do
  case "$1" in
    --vscode|--from) VSC_DIR="${2:-}"; shift 2 ;;
    --id) ID="${2:-}"; shift 2 ;;
    --name) NAME="${2:-}"; shift 2 ;;
    --description|--desc) DESCRIPTION="${2:-}"; shift 2 ;;
    --author) AUTHOR="${2:-}"; shift 2 ;;
    --homepage) HOMEPAGE="${2:-}"; shift 2 ;;
    --version) VERSION="${2:-}"; shift 2 ;;
    --permissions|--perms) PERMISSIONS="${2:-}"; shift 2 ;;
    --matches) MATCHES="${2:-}"; shift 2 ;;
    --run-at) RUN_AT="${2:-}"; shift 2 ;;
    --entry) ENTRY="${2:-}"; shift 2 ;;
    --out) OUT="${2:-}"; shift 2 ;;
    --ui) WITH_UI=1; shift ;;
    --no-ui) WITH_UI=0; shift ;;
    --force) FORCE=1; shift ;;
    -h|--help) usage; exit 0 ;;
    *) echo "Unknown option: $1" >&2; echo >&2; usage >&2; exit 1 ;;
  esac
done

# --- preflight ---------------------------------------------------------------
if [ -z "$VSC_DIR" ]; then
  echo "Error: --vscode <dir> is required." >&2
  echo >&2
  usage >&2
  exit 1
fi
if ! command -v node >/dev/null 2>&1; then
  echo "Error: node (18 or newer) is required — the converter parses package.json with it." >&2
  exit 1
fi
if [ ! -d "$VSC_DIR" ]; then
  echo "Error: $VSC_DIR is not a directory." >&2
  exit 1
fi
if [ ! -f "$VSC_DIR/package.json" ]; then
  echo "Error: $VSC_DIR/package.json not found — that does not look like a VS Code extension." >&2
  exit 1
fi

case "${RUN_AT:-document_end}" in
  document_start|document_end) ;;
  *) echo "Error: --run-at must be document_start or document_end." >&2; exit 1 ;;
esac

# --- stage the static templates ----------------------------------------------
# They are written before the id is known, then moved into place by the Node
# step below (which is what derives the id from package.json).
stage="$(mktemp -d "${TMPDIR:-/tmp}/tabsage-transition.XXXXXX")"
trap 'rm -rf "$stage"' EXIT

cat > "$stage/vscode-shim.js" <<'SHIMJS'
// Generated by transition.sh — do not hand-edit unless you are done converting.
//
// A compatibility layer that implements enough of the VS Code extension API on
// top of the Tab Sage host API for a converted extension to boot in a content
// script. Anything with no Tab Sage equivalent becomes a stub: it logs once,
// records itself in window.__tsVscUnmapped, and returns another stub instead of
// throwing, so one missing API does not take the whole extension down.
(function (global) {
  if (global.__tsVscShimLoaded) return;
  global.__tsVscShimLoaded = true;

  // `tabsage` is an in-scope local in every content script, never window.tabsage.
  var T = typeof tabsage !== "undefined" ? tabsage : null;
  function ui() {
    return typeof TabSageUI !== "undefined" ? TabSageUI : null;
  }
  function noop() {}

  var unmapped = (global.__tsVscUnmapped = global.__tsVscUnmapped || []);
  var warned = {};
  function warnUnmapped(path) {
    if (warned[path]) return;
    warned[path] = true;
    unmapped.push(path);
    console.warn("[vscode-shim] unmapped: " + path);
  }

  // Properties that must never be faked: `then` in particular, because an
  // `await` on a stub would otherwise call it and hang forever.
  var NEVER_STUB = {
    then: 1,
    catch: 1,
    finally: 1,
    toJSON: 1,
    valueOf: 1,
    nodeType: 1,
    length: 1,
    name: 1,
    prototype: 1,
  };

  // Wraps a namespace so members the shim does not implement become logged
  // stubs instead of `undefined is not a function`.
  function withFallback(path, obj) {
    return new Proxy(obj, {
      get: function (target, prop) {
        if (prop in target) return target[prop];
        if (typeof prop === "symbol" || NEVER_STUB[prop]) return undefined;
        warnUnmapped(path + "." + String(prop));
        return stub(path + "." + String(prop));
      },
    });
  }

  function stub(path) {
    var target = function () {};
    return new Proxy(target, {
      get: function (t, prop) {
        if (typeof prop === "symbol") return undefined;
        if (NEVER_STUB[prop]) return undefined;
        return stub(path + "." + String(prop));
      },
      set: function () {
        return true;
      },
      apply: function () {
        warnUnmapped(path + "()");
        return stub(path + "()");
      },
      construct: function () {
        warnUnmapped("new " + path + "()");
        return stub(path + "()");
      },
    });
  }

  /* ── core value types ──────────────────────────────────────────────────── */

  function Disposable(fn) {
    this._dispose = typeof fn === "function" ? fn : noop;
  }
  Disposable.prototype.dispose = function () {
    try {
      this._dispose();
    } catch (e) {
      console.error("[vscode-shim] dispose failed", e);
    }
  };
  Disposable.from = function () {
    var all = [].slice.call(arguments);
    return new Disposable(function () {
      all.forEach(function (d) {
        if (d && typeof d.dispose === "function") d.dispose();
      });
    });
  };

  function EventEmitter() {
    var listeners = [];
    this.event = function (listener, thisArg) {
      var bound = thisArg ? listener.bind(thisArg) : listener;
      listeners.push(bound);
      return new Disposable(function () {
        var i = listeners.indexOf(bound);
        if (i >= 0) listeners.splice(i, 1);
      });
    };
    this.fire = function (value) {
      listeners.slice().forEach(function (l) {
        try {
          l(value);
        } catch (e) {
          console.error("[vscode-shim] event listener failed", e);
        }
      });
    };
    this.dispose = function () {
      listeners.length = 0;
    };
  }

  function deadEvent() {
    return new EventEmitter().event;
  }

  function Uri(scheme, authority, uriPath, query, fragment) {
    this.scheme = scheme || "file";
    this.authority = authority || "";
    this.path = uriPath || "";
    this.query = query || "";
    this.fragment = fragment || "";
    this.fsPath = this.path;
  }
  Uri.prototype.toString = function () {
    var s = this.scheme + "://" + this.authority + this.path;
    if (this.query) s += "?" + this.query;
    if (this.fragment) s += "#" + this.fragment;
    return s;
  };
  Uri.prototype.with = function (change) {
    change = change || {};
    return new Uri(
      change.scheme != null ? change.scheme : this.scheme,
      change.authority != null ? change.authority : this.authority,
      change.path != null ? change.path : this.path,
      change.query != null ? change.query : this.query,
      change.fragment != null ? change.fragment : this.fragment,
    );
  };
  Uri.file = function (p) {
    return new Uri("file", "", String(p));
  };
  Uri.parse = function (value) {
    var m = /^([a-z][a-z0-9+.-]*):\/\/([^/?#]*)([^?#]*)(?:\?([^#]*))?(?:#(.*))?$/i.exec(
      String(value),
    );
    if (!m) return new Uri("file", "", String(value));
    return new Uri(m[1], m[2] || "", m[3] || "", m[4] || "", m[5] || "");
  };
  Uri.joinPath = function (base) {
    var parts = [].slice.call(arguments, 1).join("/");
    var joined = String(base && base.path ? base.path : base).replace(/\/+$/, "");
    return (base && base.with ? base : Uri.file(joined)).with({
      path: joined + "/" + parts.replace(/^\/+/, ""),
    });
  };

  function Position(line, character) {
    this.line = line;
    this.character = character;
  }
  function Range(start, end) {
    if (typeof start === "number") {
      this.start = new Position(arguments[0], arguments[1]);
      this.end = new Position(arguments[2], arguments[3]);
    } else {
      this.start = start;
      this.end = end;
    }
    this.isEmpty = false;
  }
  function Selection(a, b, c, d) {
    Range.call(this, a, b, c, d);
    this.anchor = this.start;
    this.active = this.end;
  }
  Selection.prototype = Object.create(Range.prototype);

  function CancellationTokenSource() {
    var em = new EventEmitter();
    var self = this;
    this.token = {
      isCancellationRequested: false,
      onCancellationRequested: em.event,
    };
    this.cancel = function () {
      self.token.isCancellationRequested = true;
      em.fire();
    };
    this.dispose = function () {
      em.dispose();
    };
  }

  function ThemeIcon(id, color) {
    this.id = id;
    this.color = color;
  }
  ThemeIcon.File = new ThemeIcon("file");
  ThemeIcon.Folder = new ThemeIcon("folder");

  function ThemeColor(id) {
    this.id = id;
  }

  function MarkdownString(value) {
    this.value = value || "";
    this.isTrusted = false;
    this.appendText = function (v) {
      this.value += v;
      return this;
    };
    this.appendMarkdown = this.appendText;
    this.appendCodeblock = function (v, lang) {
      this.value += "\n```" + (lang || "") + "\n" + v + "\n```\n";
      return this;
    };
  }

  function TreeItem(label, collapsibleState) {
    if (label && label.path) {
      this.resourceUri = label;
      this.label = undefined;
    } else {
      this.label = label;
    }
    this.collapsibleState = collapsibleState || 0;
  }

  // VS Code labels can carry codicons like "$(sync~spin) Loading" — strip them
  // before anything user-visible.
  function plain(text) {
    return String(text == null ? "" : text)
      .replace(/\$\([a-z0-9~-]+\)/gi, "")
      .trim();
  }

  /* ── the shim factory ──────────────────────────────────────────────────── */

  // opts = { meta, state, persist }
  //   meta    the window.__TS_VSC block written by transition.sh
  //   state   { config, globalState, workspaceState, secrets } — prefetched by
  //           content.js so VS Code's synchronous config reads keep working
  //   persist called after every write; content.js debounces the actual save
  global.__tsVscCreateShim = function (opts) {
    opts = opts || {};
    var meta = opts.meta || {};
    var state = opts.state || {};
    var persist = typeof opts.persist === "function" ? opts.persist : noop;
    var label = meta.name || meta.id || "extension";

    state.config = state.config || {};
    state.globalState = state.globalState || {};
    state.workspaceState = state.workspaceState || {};
    state.secrets = state.secrets || {};

    var defaults = meta.configuration || {};
    var cfgEmitter = new EventEmitter();

    function clone(v) {
      if (v === null || typeof v !== "object") return v;
      try {
        return JSON.parse(JSON.stringify(v));
      } catch (e) {
        return v;
      }
    }

    function getConfiguration(section) {
      function full(key) {
        return section ? section + "." + key : key;
      }
      var api = {
        get: function (key, fallback) {
          var k = full(key);
          if (Object.prototype.hasOwnProperty.call(state.config, k))
            return state.config[k];
          if (Object.prototype.hasOwnProperty.call(defaults, k))
            return clone(defaults[k]);
          return fallback;
        },
        has: function (key) {
          var k = full(key);
          return (
            Object.prototype.hasOwnProperty.call(state.config, k) ||
            Object.prototype.hasOwnProperty.call(defaults, k)
          );
        },
        inspect: function (key) {
          var k = full(key);
          return {
            key: k,
            defaultValue: clone(defaults[k]),
            globalValue: state.config[k],
            workspaceValue: undefined,
          };
        },
        update: function (key, value) {
          var k = full(key);
          if (value === undefined) delete state.config[k];
          else state.config[k] = value;
          persist();
          cfgEmitter.fire({
            affectsConfiguration: function (s) {
              return k.indexOf(String(s)) === 0;
            },
          });
          return Promise.resolve();
        },
      };
      // Some extensions read settings as plain properties.
      Object.keys(defaults).forEach(function (k) {
        if (section && k.indexOf(section + ".") !== 0) return;
        var short = section ? k.slice(section.length + 1) : k;
        if (short.indexOf(".") >= 0 || api[short] !== undefined) return;
        Object.defineProperty(api, short, {
          enumerable: true,
          get: function () {
            return api.get(short);
          },
        });
      });
      return api;
    }

    function memento(bag) {
      return {
        get: function (key, fallback) {
          return Object.prototype.hasOwnProperty.call(bag, key)
            ? bag[key]
            : fallback;
        },
        update: function (key, value) {
          if (value === undefined) delete bag[key];
          else bag[key] = value;
          persist();
          return Promise.resolve();
        },
        keys: function () {
          return Object.keys(bag);
        },
        setKeysForSync: noop,
      };
    }

    /* ── window ──────────────────────────────────────────────────────────── */

    function notify(message) {
      var text = plain(message);
      if (T && T.notifications && T.notifications.show) {
        Promise.resolve(T.notifications.show(label, text)).catch(noop);
      }
      var U = ui();
      if (U) U.toast(text, { variant: "ok" });
      else if (!T || !T.notifications) console.log("[" + label + "] " + text);
    }

    function pick(title, entries) {
      // entries: [{ label, sublabel, value }] -> Promise<value | undefined>
      var U = ui();
      if (U) {
        return new Promise(function (resolve) {
          var done = false;
          var m = U.modal({
            title: title,
            body: U.list({
              items: entries.map(function (e) {
                return {
                  label: e.label,
                  sublabel: e.sublabel,
                  onClick: function () {
                    done = true;
                    m.close();
                    resolve(e.value);
                  },
                };
              }),
            }),
            onClose: function () {
              if (!done) resolve(undefined);
            },
          });
        });
      }
      if (T && T.dialogs && T.dialogs.prompt) {
        var lines = entries.map(function (e, i) {
          return i + 1 + ". " + e.label;
        });
        return Promise.resolve(
          T.dialogs.prompt(title + "\n" + lines.join("\n"), "1", label),
        ).then(function (answer) {
          var i = parseInt(answer, 10) - 1;
          return entries[i] ? entries[i].value : undefined;
        });
      }
      console.warn("[vscode-shim] cannot show a picker: no UI Kit, no dialogs permission");
      return Promise.resolve(undefined);
    }

    function showMessage(kind, args) {
      var message = args[0];
      var rest = args.slice(1);
      if (
        rest.length &&
        rest[0] &&
        typeof rest[0] === "object" &&
        !Array.isArray(rest[0]) &&
        ("modal" in rest[0] || "detail" in rest[0])
      ) {
        rest.shift();
      }
      var items = rest.length === 1 && Array.isArray(rest[0]) ? rest[0] : rest;
      if (kind === "error") console.error("[" + label + "] " + plain(message));
      else if (kind === "warn") console.warn("[" + label + "] " + plain(message));

      if (!items.length) {
        notify(message);
        return Promise.resolve(undefined);
      }
      var entries = items.map(function (it) {
        return {
          label: plain(typeof it === "string" ? it : it.title || String(it)),
          value: it,
        };
      });
      var U = ui();
      if (U) {
        return new Promise(function (resolve) {
          var answered;
          var m = U.modal({
            title: label,
            body: plain(message),
            actions: entries.map(function (e, i) {
              return {
                label: e.label,
                variant: i === 0 ? "primary" : "ghost",
                onClick: function () {
                  answered = e.value;
                  resolve(e.value);
                },
              };
            }),
            onClose: function () {
              if (answered === undefined) resolve(undefined);
            },
          });
          void m;
        });
      }
      if (entries.length === 1 && T && T.dialogs && T.dialogs.confirm) {
        return Promise.resolve(
          T.dialogs.confirm(plain(message), label),
        ).then(function (ok) {
          return ok ? entries[0].value : undefined;
        });
      }
      return pick(plain(message), entries);
    }

    function showInputBox(o) {
      o = o || {};
      var question = plain(o.prompt || o.placeHolder || o.title || "Input");
      if (T && T.dialogs && T.dialogs.prompt) {
        return Promise.resolve(
          T.dialogs.prompt(question, o.value || "", label),
        ).then(function (v) {
          return v == null ? undefined : v;
        });
      }
      var v = global.prompt ? global.prompt(question, o.value || "") : null;
      return Promise.resolve(v == null ? undefined : v);
    }

    function showQuickPick(items, o) {
      o = o || {};
      return Promise.resolve(items).then(function (list) {
        list = list || [];
        var entries = list
          .filter(function (it) {
            return !(it && it.kind === -1); // separators
          })
          .map(function (it) {
            return {
              label: plain(typeof it === "string" ? it : it.label),
              sublabel: plain(
                typeof it === "string" ? "" : it.description || it.detail || "",
              ),
              value: it,
            };
          });
        var title = plain(o.title || o.placeHolder || "Select");
        if (o.canPickMany) {
          warnUnmapped("window.showQuickPick({ canPickMany: true })");
          return pick(title, entries).then(function (v) {
            return v === undefined ? undefined : [v];
          });
        }
        return pick(title, entries);
      });
    }

    function createStatusBarItem() {
      var visible = false;
      var item = {
        id: "",
        alignment: 1,
        priority: 0,
        tooltip: "",
        command: undefined,
        color: undefined,
        backgroundColor: undefined,
        accessibilityInformation: undefined,
      };
      var text = "";
      function apply() {
        if (!T || !T.badge) return;
        if (visible && text) Promise.resolve(T.badge.set(plain(text))).catch(noop);
        else Promise.resolve(T.badge.clear()).catch(noop);
      }
      Object.defineProperty(item, "text", {
        enumerable: true,
        get: function () {
          return text;
        },
        set: function (v) {
          text = v == null ? "" : String(v);
          apply();
        },
      });
      item.show = function () {
        visible = true;
        apply();
      };
      item.hide = function () {
        visible = false;
        apply();
      };
      item.dispose = item.hide;
      return item;
    }

    function createOutputChannel(name) {
      var prefix = "[" + (name || label) + "]";
      function write(v) {
        console.log(prefix, v);
      }
      return {
        name: name,
        append: write,
        appendLine: write,
        replace: write,
        clear: noop,
        show: noop,
        hide: noop,
        dispose: noop,
      };
    }

    var WEBVIEW_PREAMBLE =
      "<script>window.acquireVsCodeApi=function(){var s;return{" +
      "postMessage:function(m){parent.postMessage(m,'*')}," +
      "getState:function(){return s},setState:function(v){s=v;return v}};};" +
      "</" +
      "script>";

    function createWebviewPanel(viewType, title, showOptions, options) {
      var U = ui();
      var messages = new EventEmitter();
      var disposed = new EventEmitter();
      var frame = document.createElement("iframe");
      frame.className = "ts-vsc-webview";
      frame.setAttribute("sandbox", "allow-scripts allow-forms allow-modals");
      frame.setAttribute("referrerpolicy", "no-referrer");

      var onMessage = function (e) {
        if (e.source === frame.contentWindow) messages.fire(e.data);
      };
      global.addEventListener("message", onMessage);

      var close;
      if (U) {
        var m = U.modal({
          title: plain(title),
          body: frame,
          onClose: function () {
            teardown();
          },
        });
        close = m.close;
      } else {
        warnUnmapped("window.createWebviewPanel (no UI Kit — rendering bare)");
        var box = document.createElement("div");
        box.className = "ts-vsc-webview-box";
        box.appendChild(frame);
        document.body.appendChild(box);
        close = function () {
          if (box.parentNode) box.parentNode.removeChild(box);
        };
      }

      var html = "";
      var webview = {
        options: options || {},
        cspSource: "",
        postMessage: function (msg) {
          try {
            frame.contentWindow.postMessage(msg, "*");
            return Promise.resolve(true);
          } catch (e) {
            return Promise.resolve(false);
          }
        },
        onDidReceiveMessage: messages.event,
        asWebviewUri: function (uri) {
          warnUnmapped("Webview.asWebviewUri (local resources are not bundled)");
          return uri;
        },
      };
      Object.defineProperty(webview, "html", {
        enumerable: true,
        get: function () {
          return html;
        },
        set: function (v) {
          html = String(v == null ? "" : v);
          frame.srcdoc = WEBVIEW_PREAMBLE + html;
        },
      });

      var alive = true;
      function teardown() {
        if (!alive) return;
        alive = false;
        global.removeEventListener("message", onMessage);
        disposed.fire();
      }

      return {
        viewType: viewType,
        title: title,
        webview: webview,
        visible: true,
        active: true,
        viewColumn: 1,
        options: showOptions,
        reveal: noop,
        onDidDispose: disposed.event,
        onDidChangeViewState: deadEvent(),
        dispose: function () {
          teardown();
          close();
        },
      };
    }

    function withProgress(options, task) {
      var title = plain((options && options.title) || "Working…");
      var U = ui();
      if (U) U.toast(title, { variant: "ok" });
      var progress = {
        report: function (v) {
          if (v && v.message) console.log("[" + label + "] " + plain(v.message));
        },
      };
      var token = new CancellationTokenSource().token;
      try {
        return Promise.resolve(task(progress, token));
      } catch (e) {
        return Promise.reject(e);
      }
    }

