"use strict";
const fs = require("fs");
const path = require("path");

const env = process.env;
const VSC = path.resolve(env.TS_CWD, env.TS_VSC_DIR);
const REPO = env.TS_REPO;
const STAGE = env.TS_STAGE;
const WITH_UI = env.TS_UI === "1";
const FORCE = env.TS_FORCE === "1";

// Same list the PR validator enforces (.github/scripts/validate-pr.mjs).
const KNOWN_PERMISSIONS = [
  "content_scripts", "storage", "ai", "tabs", "notifications", "dialogs",
  "adblock", "cutout", "clipboard", "downloads", "badge", "messaging",
];
const ID_RE = /^[a-z0-9-]+$/;
const VERSION_RE = /^\d+\.\d+\.\d+$/;

const notes = [];
const warnings = [];
const blockers = [];

function die(msg) {
  console.error("Error: " + msg);
  process.exit(1);
}
function warn(msg) {
  warnings.push(msg);
  console.error("Warning: " + msg);
}

/* ── read the VS Code manifest ─────────────────────────────────────────────── */

let pkg;
try {
  pkg = JSON.parse(fs.readFileSync(path.join(VSC, "package.json"), "utf8"));
} catch (e) {
  die("could not parse " + path.join(VSC, "package.json") + ": " + e.message);
}
if (!pkg.engines || !pkg.engines.vscode) {
  warn("package.json has no engines.vscode — converting it anyway, but check that this is really a VS Code extension.");
}

function slug(value) {
  return String(value || "")
    .toLowerCase()
    .replace(/^@[^/]+\//, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

const id = env.TS_ID || slug(pkg.name);
if (!ID_RE.test(id)) {
  die(
    'could not derive a valid id from package.json name "' + (pkg.name || "") +
      '". Pass one explicitly: --id my-extension',
  );
}

function normalizeVersion(v) {
  const core = String(v || "").split(/[-+]/)[0];
  const parts = core.split(".").filter((p) => /^\d+$/.test(p));
  while (parts.length < 3) parts.push("0");
  return parts.slice(0, 3).join(".");
}
const version = env.TS_VERSION || normalizeVersion(pkg.version || "1.0.0");
if (!VERSION_RE.test(version)) {
  die('version "' + version + '" is not MAJOR.MINOR.PATCH. Pass --version 1.0.0.');
}
if (pkg.version && version !== pkg.version && !env.TS_VERSION) {
  notes.push('version "' + pkg.version + '" was normalized to "' + version + '".');
}

const name = env.TS_NAME || pkg.displayName || pkg.name || id;
const description =
  env.TS_DESC ||
  pkg.description ||
  "Converted from the VS Code extension " + (pkg.name || id) + ".";

function deriveAuthor() {
  if (env.TS_AUTHOR) return env.TS_AUTHOR;
  if (pkg.publisher) return pkg.publisher;
  if (typeof pkg.author === "string") return pkg.author.replace(/\s*<.*$/, "").trim();
  if (pkg.author && pkg.author.name) return pkg.author.name;
  return "Unknown";
}
const author = deriveAuthor();

function deriveHomepage() {
  if (env.TS_HOMEPAGE) return env.TS_HOMEPAGE;
  if (pkg.homepage) return pkg.homepage;
  const repo = pkg.repository;
  const url = typeof repo === "string" ? repo : repo && repo.url;
  if (!url) return null;
  return String(url).replace(/^git\+/, "").replace(/\.git$/, "");
}
const homepage = deriveHomepage() || null;

const matches = env.TS_MATCHES || "<all_urls>";
const runAt = env.TS_RUNAT || "document_end";

/* ── find the compiled entry ───────────────────────────────────────────────── */

const mainField = pkg.main ? String(pkg.main) : "";
const candidates = env.TS_ENTRY
  ? [env.TS_ENTRY]
  : [mainField, "out/extension.js", "dist/extension.js", "extension.js"].filter(Boolean);

let entryAbs = null;
for (const c of candidates) {
  const rel = String(c).replace(/^\.\//, "");
  const p = path.resolve(VSC, rel);
  if (fs.existsSync(p) && fs.statSync(p).isFile()) {
    entryAbs = p;
    break;
  }
}
if (!entryAbs) {
  const hint = mainField
    ? 'package.json main is "' + mainField + '", which does not exist.'
    : "no main field and no out/extension.js, dist/extension.js, or extension.js.";
  die(
    "compiled entry not found: " + hint +
      "\n  transition.sh never runs npm. Build the extension first, e.g.:" +
      "\n    (cd " + env.TS_VSC_DIR + " && npm install && npm run compile)" +
      "\n  then re-run, or point at a file directly with --entry dist/extension.js",
  );
}
if (!/\.js$/.test(entryAbs)) {
  die("the entry must be JavaScript, not " + path.extname(entryAbs) + " — compile it first.");
}

/* ── collect the modules to inline ─────────────────────────────────────────── */

const entryDir = path.dirname(entryAbs);
const SKIP_DIRS = new Set([
  "node_modules", ".git", ".vscode", ".vscode-test", "test", "tests",
  "__tests__", "coverage", "media", "images", "icons",
]);
const SKIP_FILES = new Set(["package.json", "package-lock.json", "tsconfig.json", "jsconfig.json"]);
const MAX_FILES = 400;
const MAX_BYTES = 8 * 1024 * 1024;

const modules = [];
let totalBytes = 0;

function walk(dir) {
  let entries;
  try {
    entries = fs.readdirSync(dir, { withFileTypes: true });
  } catch (e) {
    return;
  }
  for (const ent of entries) {
    const abs = path.join(dir, ent.name);
    if (ent.isDirectory()) {
      if (SKIP_DIRS.has(ent.name) || ent.name.startsWith(".")) continue;
      walk(abs);
      continue;
    }
    if (!ent.isFile()) continue;
    if (SKIP_FILES.has(ent.name)) continue;
    if (/\.(test|spec)\.js$/.test(ent.name)) continue;
    if (!/\.(js|json)$/.test(ent.name)) continue;
    const rel = path.relative(entryDir, abs).split(path.sep).join("/");
    const key = rel.replace(/\.js$/, "");
    const source = fs.readFileSync(abs, "utf8");
    totalBytes += Buffer.byteLength(source);
    modules.push({ key, rel, abs, source, json: /\.json$/.test(ent.name) });
  }
}
walk(entryDir);

if (!modules.length) die("no JavaScript found next to " + entryAbs + ".");
if (modules.length > MAX_FILES) {
  die(
    modules.length + " files would be inlined from " + entryDir +
      ". Bundle the extension (esbuild --bundle --external:vscode) and convert the bundle with --entry.",
  );
}
if (totalBytes > MAX_BYTES) {
  die(
    Math.round(totalBytes / 1024) + " KB of JavaScript would be inlined. Bundle and minify the extension first.",
  );
}
if (totalBytes > 1024 * 1024) {
  warn(Math.round(totalBytes / 1024) + " KB of JavaScript inlined — that is a lot to inject into every page.");
}

const entryKey = path
  .relative(entryDir, entryAbs)
  .split(path.sep)
  .join("/")
  .replace(/\.js$/, "");

/* ── static scan: permissions, unmapped APIs, blockers ─────────────────────── */

const allSource = modules.map((m) => m.source).join("\n");

const PERMISSION_HINTS = [
  ["clipboard", /env\s*\.\s*clipboard|\.clipboard\s*\.\s*(readText|writeText)/],
  ["notifications", /show(Information|Warning|Error)Message|setStatusBarMessage|withProgress/],
  ["dialogs", /showInputBox|showQuickPick|showOpenDialog|showSaveDialog/],
  ["storage", /getConfiguration|globalState|workspaceState|\bsecrets\b|Memento/],
  ["tabs", /openExternal|showTextDocument|tabGroups/],
  ["badge", /createStatusBarItem/],
];

let permissions;
if (env.TS_PERMS) {
  permissions = env.TS_PERMS.split(",").map((p) => p.trim()).filter(Boolean);
} else {
  permissions = ["content_scripts"];
  for (const [perm, re] of PERMISSION_HINTS) {
    if (re.test(allSource) && permissions.indexOf(perm) < 0) permissions.push(perm);
  }
}
if (permissions.indexOf("content_scripts") < 0) permissions.unshift("content_scripts");
for (const p of permissions) {
  if (KNOWN_PERMISSIONS.indexOf(p) < 0) {
    die('unknown permission "' + p + '". Valid: ' + KNOWN_PERMISSIONS.join(", ") + ".");
  }
}

const UNMAPPED_HINTS = [
  ["languages.*  (completions, hovers, diagnostics)", /\blanguages\s*\./],
  ["debug.*  (debug adapters)", /\bdebug\s*\.\s*(start|register|active)/],
  ["tasks.*  (task providers)", /\btasks\s*\.\s*(register|execute|fetch)/],
  ["window.activeTextEditor  (no editor in a browser page)", /activeTextEditor/],
  ["window.createTreeView / TreeDataProvider", /createTreeView|registerTreeDataProvider/],
  ["window.registerWebviewViewProvider  (sidebar views)", /registerWebviewViewProvider/],
  ["window.createTerminal", /createTerminal/],
  ["workspace.fs / findFiles / applyEdit  (no filesystem)", /workspace\s*\.\s*(fs|findFiles|applyEdit)/],
  ["workspace.openTextDocument", /openTextDocument/],
];
const unmapped = UNMAPPED_HINTS.filter(([, re]) => re.test(allSource)).map(([label]) => label);

const BUILTIN_RE = /require\(\s*["'](?:node:)?(fs|path|os|child_process|http|https|net|crypto|stream|zlib|worker_threads|readline|tls|dns|vm|events|util|url|assert|buffer)["']\s*\)/g;
const builtins = new Set();
let bm;
while ((bm = BUILTIN_RE.exec(allSource))) builtins.add(bm[1]);
// path, events, and util are reimplemented by the shim; the rest have nothing
// to stand on in a page and become stubs that do nothing.
const POLYFILLED = new Set(["path", "events", "util"]);
const stubbedBuiltins = [...builtins].filter((b) => !POLYFILLED.has(b)).sort();
const polyfilledBuiltins = [...builtins].filter((b) => POLYFILLED.has(b)).sort();
if (stubbedBuiltins.length) {
  blockers.push(
    "the code requires Node built-ins that do not exist in a content script: " +
      stubbedBuiltins.join(", ") +
      ". They resolve to stubs that log and do nothing, so every code path through them is dead until you replace it.",
  );
}
if (polyfilledBuiltins.length) {
  notes.push(
    "require(" + polyfilledBuiltins.join("), require(") + ") is served by the shim's own browser implementation.",
  );
}

const bareRequires = new Set();
const BARE_RE = /require\(\s*["']([^."'][^"']*)["']\s*\)/g;
let rm;
while ((rm = BARE_RE.exec(allSource))) {
  const mod = rm[1].replace(/^node:/, "");
  if (mod === "vscode" || builtins.has(mod)) continue;
  bareRequires.add(mod);
}
if (bareRequires.size) {
  blockers.push(
    "the code requires npm packages that were not inlined: " +
      [...bareRequires].sort().join(", ") +
      ". Bundle them (esbuild --bundle --external:vscode) and convert the bundle with --entry.",
  );
}

/* ── contributes ───────────────────────────────────────────────────────────── */

const contributes = pkg.contributes || {};

function asArray(v) {
  if (!v) return [];
  return Array.isArray(v) ? v : [v];
}

const commands = asArray(contributes.commands).map((c) => ({
  command: c.command,
  title: c.title || c.command,
  category: c.category || "",
})).filter((c) => c.command);

const MOD_MAP = {
  ctrl: "Ctrl", control: "Ctrl", cmd: "Cmd", meta: "Cmd", win: "Cmd", super: "Cmd",
  alt: "Alt", option: "Alt", shift: "Shift",
};

function accelerator(key, mac) {
  if (!key) return null;
  if (/\s/.test(String(key).trim())) return null; // chords are unsupported
  const winParts = String(key).split("+").map((p) => p.trim().toLowerCase());
  const macParts = mac && !/\s/.test(String(mac).trim())
    ? String(mac).split("+").map((p) => p.trim().toLowerCase())
    : null;

  const out = [];
  const seen = {};
  winParts.forEach((part, i) => {
    const isLast = i === winParts.length - 1;
    if (!isLast && MOD_MAP[part]) {
      // ctrl on Windows + cmd on macOS is exactly what Mod means.
      if (part === "ctrl" || part === "control") {
        const macHasCmd = macParts && macParts.some((p) => p === "cmd" || p === "meta");
        out.push(macHasCmd ? "Mod" : "Ctrl");
      } else {
        out.push(MOD_MAP[part]);
      }
      seen[part] = 1;
      return;
    }
    if (isLast) out.push(part.length === 1 ? part.toUpperCase() : titleKey(part));
  });
  if (out.length < 2) return null; // a bare key would fight the page
  return out.join("+");
}

function titleKey(k) {
  const special = {
    enter: "Enter", escape: "Escape", esc: "Escape", space: "Space", tab: "Tab",
    backspace: "Backspace", delete: "Delete", up: "Up", down: "Down",
    left: "Left", right: "Right", home: "Home", end: "End",
  };
  if (special[k]) return special[k];
  if (/^f\d{1,2}$/.test(k)) return k.toUpperCase();
  return k;
}

const keybindings = [];
const droppedKeys = [];
asArray(contributes.keybindings).forEach((k) => {
  if (!k || !k.command) return;
  const accel = accelerator(k.key, k.mac);
  if (!accel) {
    droppedKeys.push((k.key || "?") + " → " + k.command);
    return;
  }
  keybindings.push({ command: k.command, accelerator: accel });
});

const configuration = {};
asArray(contributes.configuration).forEach((block) => {
  const props = (block && block.properties) || {};
  Object.keys(props).forEach((key) => {
    configuration[key] = props[key] && props[key].default !== undefined
      ? props[key].default
      : undefined;
  });
});

const droppedContributes = Object.keys(contributes).filter(
  (k) => ["commands", "keybindings", "configuration"].indexOf(k) < 0,
);
if (droppedContributes.length) {
  notes.push("contributes." + droppedContributes.join(", contributes.") + " has no Tab Sage equivalent and was dropped.");
}
if (pkg.activationEvents && pkg.activationEvents.length) {
  notes.push(
    "activationEvents (" + pkg.activationEvents.join(", ") +
      ") were dropped — a Tab Sage content script always runs, at " + runAt + ".",
  );
}

/* ── output folder ─────────────────────────────────────────────────────────── */

const outDir = env.TS_OUT
  ? path.resolve(env.TS_CWD, env.TS_OUT)
  : path.join(REPO, "build", id);

if (fs.existsSync(outDir)) {
  if (!FORCE) die(outDir + " already exists. Re-run with --force to replace it.");
  const looksOurs =
    fs.existsSync(path.join(outDir, "manifest.json")) ||
    fs.readdirSync(outDir).length === 0;
  if (!looksOurs) {
    die(outDir + " exists but has no manifest.json — refusing to delete it. Pick another --out.");
  }
  fs.rmSync(outDir, { recursive: true, force: true });
}
fs.mkdirSync(outDir, { recursive: true });

const registryDir = path.join(REPO, "extensions", id);
if (fs.existsSync(registryDir)) {
  warn('extensions/' + id + ' already exists in this repo. Publishing an update needs a version above the one already there.');
  try {
    const existing = JSON.parse(fs.readFileSync(path.join(registryDir, "manifest.json"), "utf8"));
    if (existing.version && cmpVersion(existing.version, version) >= 0) {
      warn("extensions/" + id + " is at version " + existing.version + " — bump past it with --version.");
    }
  } catch (e) {
    /* nothing published yet */
  }
}

function cmpVersion(a, b) {
  const pa = a.split(".").map(Number);
  const pb = b.split(".").map(Number);
  for (let i = 0; i < 3; i++) {
    if ((pa[i] || 0) !== (pb[i] || 0)) return (pa[i] || 0) - (pb[i] || 0);
  }
  return 0;
}

/* ── write the extension ───────────────────────────────────────────────────── */

for (const f of ["vscode-shim.js", "content.js", "style.css"]) {
  fs.copyFileSync(path.join(STAGE, f), path.join(outDir, f));
}

let hasUi = WITH_UI;
if (WITH_UI) {
  const kit = path.join(REPO, "ui-kit", "dist", "tabsage-ui.min.js");
  if (fs.existsSync(kit)) {
    fs.copyFileSync(kit, path.join(outDir, "tabsage-ui.js"));
  } else {
    hasUi = false;
    warn(
      "ui-kit/dist/tabsage-ui.min.js not found, so the UI Kit was not vendored. Build it with `node ui-kit/build.mjs` and re-run; menus and pickers fall back to dialogs until then.",
    );
  }
}

// contributes.js — the declarative half of the VS Code manifest, as data.
const vscMeta = {
  id,
  name,
  entry: entryKey,
  commands,
  keybindings,
  configuration,
  packageJSON: {
    name: pkg.name,
    displayName: pkg.displayName,
    version: pkg.version,
    publisher: pkg.publisher,
    description: pkg.description,
    contributes: { commands },
  },
};
fs.writeFileSync(
  path.join(outDir, "contributes.js"),
  "// Generated by transition.sh — the declarative parts of the VS Code manifest.\n" +
    "// contributes.commands become launcher menu items, contributes.keybindings\n" +
    "// become tabsage.shortcuts, contributes.configuration supplies setting defaults.\n" +
    "window.__TS_VSC = " +
    JSON.stringify(vscMeta, null, 2) +
    ";\n",
);

// extension.js — every source file in Node's own module wrapper, so `require`,
// `module`, and `exports` stay module-local instead of leaking onto the page.
function stripSource(source) {
  return source
    .replace(/^#!.*\n/, "")
    .replace(/^\/\/# sourceMappingURL=.*$/gm, "")
    .replace(/\s+$/, "");
}

const WRAPPER_ARGS =
  "require, module, exports, __filename, __dirname, process, Buffer, global";

let bundle =
  "// Generated by transition.sh from " + path.relative(VSC, entryAbs).split(path.sep).join("/") +
  " in " + (pkg.name || id) + " " + (pkg.version || "") + ".\n" +
  "// Each module keeps Node's module wrapper so require/module/exports stay\n" +
  "// local — defining them globally would break host pages that UMD-sniff them.\n" +
  "window.__tsVscModules = window.__tsVscModules || {};\n\n";

for (const m of modules) {
  bundle += "window.__tsVscModules[" + JSON.stringify(m.key) + "] = function (" + WRAPPER_ARGS + ") {\n";
  bundle += m.json
    ? "module.exports = " + m.source.trim() + ";"
    : stripSource(m.source);
  bundle += "\n};\n\n";
}
fs.writeFileSync(path.join(outDir, "extension.js"), bundle);

// manifest.json — same key order as `tabsage new`.
const js = [];
if (hasUi) js.push("tabsage-ui.js");
js.push("contributes.js", "vscode-shim.js", "extension.js", "content.js");

const manifest = {
  id,
  name,
  version,
  description,
  author,
  homepage,
  permissions,
  content_scripts: [{ matches: [matches], js, css: ["style.css"], run_at: runAt }],
};
fs.writeFileSync(path.join(outDir, "manifest.json"), JSON.stringify(manifest, null, 2) + "\n");

/* ── README with the conversion report ────────────────────────────────────── */

function bullets(list) {
  return list.length ? list.map((l) => "- " + l).join("\n") : "- None.";
}

const readme = [
  "# " + name,
  "",
  description,
  "",
  "Converted from the VS Code extension `" + (pkg.name || id) + "` " +
    (pkg.version ? "(" + pkg.version + ") " : "") + "by `transition.sh`.",
  "",
  "## What it touches",
  "",
  "- Runs on: `" + matches + "` at `" + runAt + "` (never in incognito).",
  "- State (settings, globalState, workspaceState) lives under one `tabsage.storage` key, `__vsc_state`.",
  "- Review this section by hand before publishing: describe what the extension actually reads or changes.",
  "",
  "## Permissions",
  "",
  permissions.map((p) => "`" + p + "`").join(", ") +
    ". (`page`, `runtime`, and `shortcuts` need no permission.)",
  "",
  "## Commands",
  "",
  commands.length
    ? commands.map((c) => "- **" + (c.category ? c.category + ": " : "") + c.title + "** — `" + c.command + "`").join("\n")
    : "- None contributed.",
  "",
  "## Conversion notes",
  "",
  "- Entry: `" + path.relative(VSC, entryAbs).split(path.sep).join("/") + "` (" + modules.length +
    " module" + (modules.length === 1 ? "" : "s") + " inlined, " + Math.round(totalBytes / 1024) + " KB).",
  "- Commands mapped to launcher menu items: " + commands.length + ".",
  "- Keybindings mapped to `tabsage.shortcuts`: " +
    (keybindings.length ? keybindings.map((k) => "`" + k.accelerator + "` → `" + k.command + "`").join(", ") : "none") + ".",
  droppedKeys.length
    ? "- Keybindings dropped (chords and bare keys are unsupported): " + droppedKeys.map((k) => "`" + k + "`").join(", ") + "."
    : "- No keybindings were dropped.",
  "",
  "### Blockers",
  "",
  bullets(blockers),
  "",
  "### VS Code APIs with no Tab Sage equivalent",
  "",
  "These were found in the source and resolve to logged stubs at runtime. Check",
  "`window.__tsVscUnmapped` in a page where the extension ran for the live list.",
  "",
  bullets(unmapped),
  "",
  "### Dropped from the VS Code manifest",
  "",
  bullets(notes),
  "",
  warnings.length ? "### Warnings\n\n" + bullets(warnings) + "\n" : "",
  "### Before publishing",
  "",
  "- [ ] Load it unpacked in Tab Sage and exercise every command.",
  "- [ ] Replace stubbed APIs, or delete the code paths that need them.",
  "- [ ] Rewrite this README to describe the extension, not the conversion.",
  "- [ ] Copy the folder to `extensions/" + id + "/` and open one PR for it.",
  "",
  "## Changes",
  "",
  "- " + version + " — Initial release.",
  "",
].join("\n");
fs.writeFileSync(path.join(outDir, "README.md"), readme.replace(/\n{3,}/g, "\n\n"));

/* ── validate exactly like the PR validator would ─────────────────────────── */

const problems = [];
if (!ID_RE.test(manifest.id)) problems.push('id "' + manifest.id + '" must match ^[a-z0-9-]+$');
if (manifest.id !== path.basename(outDir) && !env.TS_OUT) {
  problems.push("id must equal the folder name");
}
if (!VERSION_RE.test(manifest.version)) problems.push("version must be MAJOR.MINOR.PATCH");
for (const field of ["name", "description", "author"]) {
  if (typeof manifest[field] !== "string" || !manifest[field].trim()) {
    problems.push(field + " must be a non-empty string");
  }
}
for (const p of manifest.permissions) {
  if (KNOWN_PERMISSIONS.indexOf(p) < 0) problems.push('unknown permission "' + p + '"');
}
for (const entry of manifest.content_scripts) {
  if (!entry.matches || !entry.matches.length) problems.push("content_scripts needs matches");
  if (["document_start", "document_end"].indexOf(entry.run_at) < 0) {
    problems.push('run_at must be document_start or document_end');
  }
  for (const rel of [].concat(entry.js || [], entry.css || [])) {
    if (rel.startsWith("/") || rel.includes("..") || rel.includes(":")) {
      problems.push('"' + rel + '" must be a relative path inside the extension');
    } else if (!fs.existsSync(path.join(outDir, rel))) {
      problems.push('"' + rel + '" is referenced but missing');
    }
  }
}
if (problems.length) {
  console.error("Error: the generated manifest is invalid:");
  problems.forEach((p) => console.error("  - " + p));
  process.exit(1);
}

/* ── report ───────────────────────────────────────────────────────────────── */

const rel = path.relative(env.TS_CWD, outDir) || outDir;
console.log("Converted " + (pkg.name || id) + " " + (pkg.version || "") + " → " + rel);
console.log("  manifest ok  id=" + id + "  version=" + version);
console.log("  permissions  " + permissions.join(", "));
console.log("  modules      " + modules.length + " inlined (" + Math.round(totalBytes / 1024) + " KB)");
console.log("  commands     " + commands.length + " → launcher menu");
console.log("  keybindings  " + keybindings.length + " mapped" + (droppedKeys.length ? ", " + droppedKeys.length + " dropped" : ""));
console.log("  ui kit       " + (hasUi ? "vendored" : "not vendored"));
if (unmapped.length) {
  console.log("  unmapped     " + unmapped.length + " VS Code API area(s) — see README.md");
}
if (blockers.length) {
  console.log("");
  blockers.forEach((b) => console.log("  BLOCKER: " + b));
}
CONVERTMJS

echo
